import * as React from 'react';
import * as S from '@primasoftllc/design-system';
import '@primasoftllc/design-system/styles.css';

function HeaderExample(props) {
    var t = React.useState('m');
    var message = React.useState('');
    const [compact, setCompact] = React.useState(() => matchMedia('(max-width: 600px)').matches);
    React.useEffect(() => {
        const media = matchMedia('(max-width: 600px)');
        const update = () => setCompact(media.matches);
        media.addEventListener('change', update);
        return () => media.removeEventListener('change', update);
    }, []);
    return <div className="col header-stage">
    <S.DsAppHeader product={compact ? '' : 'Aurora'} logoSrc={compact ? undefined : '../assets/logo/AuroraWhite.png'} env={compact ? undefined : 'DEV'} actions={[!compact && <S.DsIconButton key={'h'} icon={'help'} label={'Справка'} tone={'onHeader'} onClick={() => message[1]('Открыта справка.')}/>, <S.DsUserMenu key={'u'} name={'a.ivanov'} items={[{ id: 'profile', label: 'Профиль', icon: 'person' }, { id: 'settings', label: 'Настройки', icon: 'settings' }]} onSelect={item => message[1]('Выбрано: ' + item.label)}/>]}>
    <S.DsTabs tone={'onHeader'} stack={props.stack} active={t[0]} onChange={t[1]} items={[
            { id: 'm', label: 'Мониторинг', icon: 'map' }, { id: 'r', label: 'Отчёты', icon: 'assessment' },
            { id: 'n', label: 'Оповещения', icon: 'notifications', badge: 3 }
        ]}/>
    </S.DsAppHeader>
    <p role="status" aria-label="Результат выбора">{message[0] || 'Открыт раздел: ' + { m: 'Мониторинг', r: 'Отчёты', n: 'Оповещения' }[t[0]]}</p>
    </div>;
}
function App() {
    return <div className="dsappheader-example">
    <style>{exampleStyles}</style>
    <HeaderExample stack={true}/>
    </div>;
}

const exampleStyles = ".dsappheader-example{font:var(--ds-type-body);color:var(--ds-fg)}\n.dsappheader-example .demo-stack{display:flex;flex-direction:column;gap:16px;min-width:0}\n.dsappheader-example p{margin:0}\n.dsappheader-example .col{display:flex;flex-direction:column;gap:12px}\n.dsappheader-example .header-stage{min-height:180px}";

export { App as Example };

